#include <bits/stdc++.h>
using namespace std;

int main(void){
	int n;
	string s;
	stack<char> st;

	cin>>s;
	n=s.size();
	for(int i=0;i<n;i++){
		if((s[i]=='(')||(s[i]=='[')||(s[i]=='<'))st.push(s[i]);
		else{
			bool flag=false;
			if(st.empty()){
			  cout<<"No"<<endl;
				return 0;
			}
			if((s[i]==')')&&(st.top()!='('))flag=true;
			if((s[i]==']')&&(st.top()!='['))flag=true;
			if((s[i]=='>')&&(st.top()!='<'))flag=true;
			if(flag){
				cout<<"No"<<endl;
				return 0;
			}
			st.pop();
		}
	}
	if(st.empty())cout<<"Yes"<<endl;
	else cout<<"No"<<endl;
}
